INSERT INTO diagnostic_questions(code,label,sort_order) VALUES ('q1','Como a empresa se apresenta hoje, em uma frase?',0);
INSERT INTO diagnostic_questions(code,label,sort_order) VALUES ('q2','Quem é o cliente ideal? (perfil, região, ticket médio)',1);
INSERT INTO diagnostic_questions(code,label,sort_order) VALUES ('q3','Quem são os principais concorrentes e o que diferencia vocês?',2);
INSERT INTO diagnostic_questions(code,label,sort_order) VALUES ('q4','Qual o principal objetivo para os próximos 3 meses?',3);
INSERT INTO diagnostic_questions(code,label,sort_order) VALUES ('q5','O que já foi feito de marketing? O que funcionou e o que não funcionou?',4);
INSERT INTO diagnostic_questions(code,label,sort_order) VALUES ('q6','Como os clientes chegam hoje? (indicação, Instagram, Google…)',5);
