INSERT INTO diagnostic_questions(code,label,sort_order) VALUES ('q8','Quem aprova os conteúdos e qual o melhor canal para falar com essa pessoa?',7);
INSERT INTO diagnostic_questions(code,label,sort_order) VALUES ('q9','Quais datas, lançamentos ou campanhas importantes vêm nos próximos meses?',8);
INSERT INTO flow_stages(code,name,area,sla_days,description,done_criteria,sort_order) VALUES ('s-brief','Briefing com o cliente','Relacionamento',2,'Ponto único de contato com o cliente: entende a demanda, coleta materiais e acessos e alinha prazos. A equipe de produção não precisa falar com o cliente.','Briefing registrado no projeto, materiais recebidos e prazo combinado.',0);
INSERT INTO flow_stages(code,name,area,sla_days,description,done_criteria,sort_order) VALUES ('s-estr','Estratégia e foco de marketing','Estratégia',3,'Define objetivo, público, mensagem principal, formatos, roteiro e pauta de cada peça, ligando tudo ao foco de marketing do cliente.','Roteiro e pauta aprovados internamente e enviados para produção.',1);
INSERT INTO flow_stages(code,name,area,sla_days,description,done_criteria,sort_order) VALUES ('s-capt','Captação de vídeo e foto','Audiovisual',3,'Planeja e executa a gravação e as fotos seguindo o roteiro: locação, equipamento e lista de cenas.','Material bruto organizado na pasta do cliente.',2);
INSERT INTO flow_stages(code,name,area,sla_days,description,done_criteria,sort_order) VALUES ('s-edit','Edição do material','Audiovisual',3,'Edita vídeos e trata fotos no padrão visual do cliente: cortes, legendas, trilha e ganchos.','Versão final exportada nos formatos de cada canal.',3);
INSERT INTO flow_stages(code,name,area,sla_days,description,done_criteria,sort_order) VALUES ('s-design','Design das peças','Design',3,'Cria carrosséis, posts, capas e anúncios a partir da pauta e do material captado.','Peças finalizadas e enviadas para a biblioteca de criativos.',4);
INSERT INTO flow_stages(code,name,area,sla_days,description,done_criteria,sort_order) VALUES ('s-rev','Revisão interna','Estratégia',1,'Confere se cada peça cumpre o objetivo, o padrão da marca, o texto e as regras do segmento antes de ir para o cliente.','Checklist de qualidade aprovado.',5);
INSERT INTO flow_stages(code,name,area,sla_days,description,done_criteria,sort_order) VALUES ('s-aprov','Aprovação do cliente','Relacionamento',3,'Envia ao cliente, cobra o retorno e devolve os ajustes consolidados em uma única rodada para a produção.','Aprovação registrada por escrito.',6);
INSERT INTO flow_stages(code,name,area,sla_days,description,done_criteria,sort_order) VALUES ('s-pub','Publicação e entrega','Relacionamento',1,'Agenda ou publica as peças, entrega os arquivos e atualiza o catálogo do mês.','Peças publicadas e catálogo marcado como Publicado.',7);
INSERT INTO services(legacy_id,name,tagline,what,why_items,for_who,deliverables,metrics,time_to_result,questions,default_steps,sort_order) VALUES ('s1','Gestão de tráfego pago','Anúncios que colocam a sua empresa na frente de quem já está procurando o que você vende.','Planejamos, criamos e otimizamos campanhas pagas no Meta (Instagram e Facebook) e no Google. Cada real investido é acompanhado e ajustado toda semana para trazer mais contatos pelo menor custo.',ARRAY['Resultado rápido: as campanhas começam a gerar contatos já nas primeiras semanas','Previsibilidade: você sabe quanto custa cada cliente novo e pode planejar o crescimento','Alcança quem já tem intenção de compra, no Google e nas redes','Escala: quando funciona, basta aumentar o investimento','Tudo é medido, então nada é decidido no achismo']::text[],ARRAY['Empresas que precisam de mais clientes de forma constante','Quem vai lançar um produto, serviço ou campanha','Negócios que dependem só de indicação e querem sair disso']::text[],ARRAY['Estratégia de campanhas e públicos','Configuração de pixel, conversões e rastreamento','Criativos dos anúncios em parceria com o time de design e audiovisual','Otimização semanal das campanhas','Relatório mensal com resultados e próximos passos']::text[],ARRAY['Custo por lead (CPL)','Custo por venda (CPA)','Retorno sobre o investimento em anúncios (ROAS)','Taxa de cliques (CTR)']::text[],'Primeiros contatos em 1 a 3 semanas; campanhas estáveis e otimizadas a partir do 2º mês.',ARRAY['Quanto vocês podem investir em anúncios por mês?','Qual produto ou serviço traz mais lucro?','Quanto vale um cliente novo para vocês?','Já anunciaram antes? Como foi?']::text[],ARRAY['Acessos e pixel configurados','Estratégia de campanhas aprovada','Criativos produzidos','Campanhas no ar','Primeiro relatório de resultados']::text[],1);
INSERT INTO services(legacy_id,name,tagline,what,why_items,for_who,deliverables,metrics,time_to_result,questions,default_steps,sort_order) VALUES ('s2','Conteúdo para redes sociais','Um perfil que mostra quem vocês são, gera confiança e faz o cliente lembrar da sua marca.','Cuidamos do planejamento, da criação e da publicação dos conteúdos: reels, carrosséis, posts e stories, com captação audiovisual e design próprios, sempre ligados a um objetivo de marketing.',ARRAY['Gera autoridade: quem aparece com consistência vira referência no assunto','As pessoas pesquisam o seu perfil antes de comprar; ele precisa convencer','Aproxima a marca do público e cria relacionamento','Fortalece os anúncios: tráfego pago converte melhor num perfil bem cuidado','Você ganha tempo para focar no seu negócio']::text[],ARRAY['Empresas com perfil parado ou sem padrão visual','Profissionais que querem ser reconhecidos como referência','Marcas que vendem pela confiança e pelo relacionamento']::text[],ARRAY['Planejamento mensal (catálogo) com pautas e objetivos','Roteiros e legendas','Captação e edição de vídeos','Design de posts e carrosséis','Publicação, acompanhamento e relatório mensal']::text[],ARRAY['Alcance e crescimento de seguidores qualificados','Engajamento (salvamentos, compartilhamentos, comentários)','Mensagens e contatos vindos do perfil','Visualizações dos vídeos']::text[],'Perfil organizado no 1º mês; crescimento consistente de alcance e autoridade entre o 3º e o 6º mês.',ARRAY['Quais assuntos vocês dominam e gostam de falar?','Quem pode aparecer nos vídeos?','Quais perfis vocês admiram?','Com que frequência conseguimos captar conteúdo?']::text[],ARRAY['Planejamento do mês aprovado','Roteiros e pautas aprovados','Captação audiovisual','Design e edição','Aprovação do cliente','Publicação']::text[],2);
INSERT INTO services(legacy_id,name,tagline,what,why_items,for_who,deliverables,metrics,time_to_result,questions,default_steps,sort_order) VALUES ('s3','Marketing de conteúdo e inbound','Atrair, educar e converter clientes com conteúdo, sem depender só de anúncios.','Criamos conteúdos que respondem às dúvidas do seu cliente (blog, materiais ricos, e-mails) e montamos a estrutura que transforma visitantes em contatos e contatos em clientes, de forma automática.',ARRAY['Atrai clientes de forma contínua, mesmo sem anúncio ativo','O cliente chega mais preparado e a venda fica mais fácil','O conteúdo continua trabalhando por meses ou anos','Reduz o custo por cliente no longo prazo','Aparece no Google quando o cliente pesquisa']::text[],ARRAY['Empresas com venda mais consultiva ou ticket mais alto','Negócios em que o cliente pesquisa bastante antes de comprar','Quem quer reduzir a dependência de mídia paga']::text[],ARRAY['Definição de persona e jornada de compra','Plano editorial e artigos otimizados para o Google','Materiais ricos (e-book, guia, checklist) para captar contatos','Landing pages de captura','Fluxos de e-mail e nutrição dos contatos','Relatório mensal de visitas, leads e oportunidades']::text[],ARRAY['Visitas orgânicas ao site','Leads gerados por conteúdo','Taxa de conversão das landing pages','Oportunidades de venda geradas']::text[],'Primeiros leads com os materiais ricos em 1 a 2 meses; tráfego orgânico ganha força entre o 4º e o 8º mês.',ARRAY['Quais dúvidas o cliente sempre faz antes de comprar?','Quanto tempo leva uma venda, do primeiro contato ao fechamento?','Vocês já têm site com blog?','Usam alguma ferramenta de e-mail ou CRM?']::text[],ARRAY['Persona e jornada definidas','Plano editorial aprovado','Material rico produzido','Landing page e automação no ar','Primeiros conteúdos publicados','Relatório de leads']::text[],3);
INSERT INTO services(legacy_id,name,tagline,what,why_items,for_who,deliverables,metrics,time_to_result,questions,default_steps,sort_order) VALUES ('s4','Sites e landing pages','A sua vitrine aberta 24 horas, feita para transformar visita em contato.','Desenvolvemos sites institucionais e landing pages rápidos, bonitos e pensados para conversão, com textos estratégicos, design alinhado à marca e integração com WhatsApp, formulários e ferramentas de medição.',ARRAY['Passa credibilidade: o cliente confere o site antes de fechar','Converte melhor as campanhas de anúncio','Você é dono do canal, ao contrário das redes sociais','Aparece no Google para quem procura o seu serviço','Centraliza informações e reduz perguntas repetidas']::text[],ARRAY['Empresas sem site ou com site desatualizado','Quem vai investir em tráfego pago e precisa de uma página que converta','Lançamentos, eventos e campanhas específicas']::text[],ARRAY['Mapa do site e estrutura das páginas','Textos (copy) focados em conversão','Layout exclusivo na identidade da marca','Versão para celular','Integração com WhatsApp, formulários e Google Analytics','Publicação e treinamento básico']::text[],ARRAY['Taxa de conversão (visitas que viram contato)','Tempo de carregamento','Origem das visitas','Contatos gerados pelo site']::text[],'Landing page em 2 a 3 semanas; site institucional em 4 a 8 semanas, dependendo do tamanho.',ARRAY['Vocês já têm domínio e hospedagem?','Qual a ação principal que o visitante deve fazer?','Quais páginas não podem faltar?','Têm textos, fotos e depoimentos prontos?']::text[],ARRAY['Briefing e mapa do site','Wireframe aprovado','Layout aprovado','Conteúdo enviado pelo cliente','Desenvolvimento','Publicação e testes']::text[],4);
INSERT INTO services(legacy_id,name,tagline,what,why_items,for_who,deliverables,metrics,time_to_result,questions,default_steps,sort_order) VALUES ('s5','Identidade visual e branding','Uma marca clara, reconhecível e coerente em tudo o que a empresa mostra.','Construímos ou renovamos a marca a partir do posicionamento: o que a empresa defende, como fala e como aparece. Isso vira logo, paleta, tipografia e um manual para aplicar tudo com consistência.',ARRAY['Diferencia a empresa da concorrência','Permite cobrar mais, porque marcas fortes passam mais valor','Deixa toda a comunicação coerente, das redes à fachada','Facilita o trabalho de todo o marketing daqui para frente','Cria reconhecimento: o cliente lembra de você']::text[],ARRAY['Empresas novas que vão começar do jeito certo','Marcas que cresceram e não representam mais o negócio','Quem vai mudar de público, de preço ou de posicionamento']::text[],ARRAY['Imersão e diagnóstico da marca','Plataforma de marca (propósito, posicionamento, tom de voz)','Logo e variações','Paleta de cores e tipografia','Aplicações (redes, papelaria, fachada)','Manual da marca']::text[],ARRAY['Reconhecimento da marca','Percepção de valor e ticket médio','Consistência visual nos canais']::text[],'Projeto completo em 4 a 8 semanas.',ARRAY['O que a marca precisa transmitir em uma palavra?','O que não gostam na marca atual?','Quais marcas vocês admiram, mesmo de outros setores?','Onde a marca mais aparece hoje?']::text[],ARRAY['Imersão e diagnóstico','Plataforma de marca aprovada','Proposta de logo','Ajustes e aprovação','Manual da marca entregue']::text[],5);
